def build(data, r, c):
    dsum = [[0]*c for _ in range(r)]
    for i in range(r):
        row = 0
        for j in range(c):
            if data[i][j] == '@':
                row += 1
            up = 0 if i == 0 else dsum[i-1][j]
            dsum[i][j] = up + row
    return dsum

def solve(data, r, c, h, v):
    dsum = build(data, r, c)
    if dsum[r-1][c-1] % ((h+1)*(v+1)) != 0:
        return False
    piece = dsum[r-1][c-1] // ((h+1)*(v+1))
    for i in range(r-1):
        for j in range(c-1):
            if dsum[i][j] == piece and dsum[i][c-1] == dsum[r-1][j] == 2*piece:
                return True
    return False

