            addressBuilder.append((String) result.get("venue_address4"));
        }
        e.setStreetAddress(addressBuilder.toString().trim());
        e.setZipCode((String) result.get("venue_zip"));
        e.setUrl((String) result.get("event_url"));
        events.add(e);
    }
    return events;
}

